import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"Glossary Basics","description":"","frontmatter":{},"headers":[],"relativePath":"glossaries/basics.md","filePath":"glossaries/basics.md"}'),l={name:"glossaries/basics.md"};function s(o,e,n,h,d,g){return a(),i("div",null,e[0]||(e[0]=[r('<h1 id="glossary-basics" tabindex="-1">Glossary Basics <a class="header-anchor" href="#glossary-basics" aria-label="Permalink to &quot;Glossary Basics&quot;">​</a></h1><p>Glossaries (termbases) help ensure consistent terminology across your translations.</p><h2 id="what-is-a-glossary" tabindex="-1">What is a Glossary? <a class="header-anchor" href="#what-is-a-glossary" aria-label="Permalink to &quot;What is a Glossary?&quot;">​</a></h2><p>A glossary is a database of terms with their translations:</p><table tabindex="0"><thead><tr><th>Source (EN)</th><th>Target (NL)</th><th>Domain</th><th>Notes</th></tr></thead><tbody><tr><td>software</td><td>software</td><td>IT</td><td>Don&#39;t translate</td></tr><tr><td>click</td><td>klikken</td><td>IT</td><td>Verb</td></tr><tr><td>machine learning</td><td>machinaal leren</td><td>AI</td><td>Official term</td></tr></tbody></table><h2 id="why-use-glossaries" tabindex="-1">Why Use Glossaries? <a class="header-anchor" href="#why-use-glossaries" aria-label="Permalink to &quot;Why Use Glossaries?&quot;">​</a></h2><ol><li><strong>Consistency</strong>: Same term = same translation every time</li><li><strong>Efficiency</strong>: Don&#39;t look up the same term twice</li><li><strong>Quality</strong>: Use approved terminology</li><li><strong>Client requirements</strong>: Follow style guides</li></ol><h2 id="glossary-features-in-supervertaler" tabindex="-1">Glossary Features in Supervertaler <a class="header-anchor" href="#glossary-features-in-supervertaler" aria-label="Permalink to &quot;Glossary Features in Supervertaler&quot;">​</a></h2><h3 id="automatic-highlighting" tabindex="-1">Automatic Highlighting <a class="header-anchor" href="#automatic-highlighting" aria-label="Permalink to &quot;Automatic Highlighting&quot;">​</a></h3><p>Terms from active glossaries are highlighted in the source text:</p><ul><li>Green background by default</li><li>Hover to see the translation</li><li>Higher priority = darker shade</li></ul><h3 id="multiple-glossaries" tabindex="-1">Multiple Glossaries <a class="header-anchor" href="#multiple-glossaries" aria-label="Permalink to &quot;Multiple Glossaries&quot;">​</a></h3><p>Maintain separate glossaries for:</p><ul><li>Different clients</li><li>Different domains (legal, medical, IT)</li><li>Different projects</li></ul><h3 id="priority-levels" tabindex="-1">Priority Levels <a class="header-anchor" href="#priority-levels" aria-label="Permalink to &quot;Priority Levels&quot;">​</a></h3><p>Assign priority (1-10) to terms:</p><ul><li>Priority 1 (highest): Must be used</li><li>Priority 5: Standard terms</li><li>Priority 10: Optional/suggestions</li></ul><h3 id="forbidden-terms" tabindex="-1">Forbidden Terms <a class="header-anchor" href="#forbidden-terms" aria-label="Permalink to &quot;Forbidden Terms&quot;">​</a></h3><p>Mark terms as &quot;forbidden&quot; to flag text that should NOT be translated or should be avoided.</p><h2 id="creating-your-first-glossary" tabindex="-1">Creating Your First Glossary <a class="header-anchor" href="#creating-your-first-glossary" aria-label="Permalink to &quot;Creating Your First Glossary&quot;">​</a></h2><ol><li>Go to <strong>Project resources → Glossaries</strong></li><li>Click <strong>+ Create Glossary</strong></li><li>Enter a name (e.g., &quot;Client ABC Terminology&quot;)</li><li>Choose source and target languages</li><li>Click <strong>Create</strong></li></ol><h2 id="adding-terms" tabindex="-1">Adding Terms <a class="header-anchor" href="#adding-terms" aria-label="Permalink to &quot;Adding Terms&quot;">​</a></h2><h3 id="manually" tabindex="-1">Manually <a class="header-anchor" href="#manually" aria-label="Permalink to &quot;Manually&quot;">​</a></h3><ol><li>Click on your glossary</li><li>Click <strong>+ Add Term</strong></li><li>Enter source term, target term</li><li>Optionally add domain, notes, priority</li><li>Click <strong>Save</strong></li></ol><h3 id="from-selection" tabindex="-1">From Selection <a class="header-anchor" href="#from-selection" aria-label="Permalink to &quot;From Selection&quot;">​</a></h3><ol><li>Select text in the source column</li><li>Right-click → <strong>Add to Glossary</strong></li><li>Enter the target translation</li><li>Choose which glossary to add to</li></ol><h3 id="import-from-file" tabindex="-1">Import from File <a class="header-anchor" href="#import-from-file" aria-label="Permalink to &quot;Import from File&quot;">​</a></h3><ol><li>Go to <strong>Project resources → Glossaries</strong></li><li>Click <strong>Import</strong></li><li>Select a TSV file (tab-separated: source, target, domain, notes)</li><li>Watch the progress dialog</li></ol><h2 id="glossary-settings" tabindex="-1">Glossary Settings <a class="header-anchor" href="#glossary-settings" aria-label="Permalink to &quot;Glossary Settings&quot;">​</a></h2><h3 id="activation" tabindex="-1">Activation <a class="header-anchor" href="#activation" aria-label="Permalink to &quot;Activation&quot;">​</a></h3><p>Glossaries must be activated to show matches:</p><ul><li>✅ <strong>Read</strong>: Terms are highlighted and shown in lookups</li><li>✅ <strong>Write</strong>: New terms can be added during translation</li></ul><h3 id="highlight-style" tabindex="-1">Highlight Style <a class="header-anchor" href="#highlight-style" aria-label="Permalink to &quot;Highlight Style&quot;">​</a></h3><p>Choose how terms appear in the grid:</p><ul><li><strong>Background</strong>: Green background shading</li><li><strong>Dotted Underline</strong>: Subtle underline</li><li><strong>Semibold</strong>: Bold text</li></ul><p>Go to <strong>Settings → View Settings → Glossary Highlight Style</strong>.</p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./creating.html">Creating Glossaries</a></li><li><a href="./importing.html">Importing Terms</a></li><li><a href="./highlighting.html">Term Highlighting</a></li><li><a href="./termlens.html">TermLens (Inline Terminology)</a></li><li><a href="./extraction.html">Term Extraction</a></li></ul>',39)]))}const m=t(l,[["render",s]]);export{u as __pageData,m as default};
